clickNextMonth/page.evaluate(() => {
    const pop = document.querySelector(".react-datepicker");
    if (!pop) return false;
    const header = pop.querySelector('[class*="header"]') || pop;
    const btns = Array.from(header.querySelectorAll("button"))
      .filter(b => !(b as HTMLButtonElement).disabled && b.getBoundingClientRect().width > 0);
    if (!btns.length) return false;
    btns.sort((a, b) => b.getBoundingClientRect().x - a.getBoundingClientRect().x);
    (btns[0] as HTMLElement).click();
    return true;
  }).catch()#0

pickerDump/page.evaluate(`(() => {
    const pop = document.querySelector('.react-datepicker');
    if (!pop) return '(no .react-datepicker popup)';
    const days = Array.from(pop.querySelectorAll('.react-datepicker__day'));
    const enabled = days.filter(x => !x.className.toString().includes('--disabled') && !x.className.toString().includes('--outside-month'));
    return JSON.stringify({ enabled: enabled.slice(0, 8).map(x => x.getAttribute('aria-label') || (x.textContent || '').trim()), html: pop.outerHTML.replace(/\\s+/g, ' ').slice(0, 400) });
  })()`).catch()#0

